(26424, 'Hebrews 13:4', 'Hebrews', 13, 4, 'ټول باید واده ته درناوی ولري او ښځې او مېړونه باید یو بل ته وفادار اوسي، ځکه چې خدای به بد‌اخلاقه او زناکاره خلک محکوم کړي.', 'تول باید واده ته درناوی ولری او شجې او مېرونه باید یو بل ته وفادار اوسی، جکه چې خدای به بد‌اخلاقه او زناکاره خلک محکوم کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26425, 'Hebrews 13:5', 'Hebrews', 13, 5, 'په خپل ژوند کې د پیسو سره د مینې کولو نه ځان لېرې وساتئ او څه چې لرئ په هغو باندې قناعت وکړئ، ځکه چې خدای ویلي دي: «زه به هېڅکله تاسو یوازې پرېنږدم او هېڅکله به مو نه هېروم.»', 'په خپل ژوند کې د پیسو سره د مینې کولو نه جان لېرې وساتی او چه چې لری په هغو باندې قناعت وکری، جکه چې خدای ویلی دی: «زه به هېچکله تاسو یوازې پرېنزدم او هېچکله به مو نه هېروم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26426, 'Hebrews 13:6', 'Hebrews', 13, 6, 'نو مونږ په ډاډه زړه ویلی شو: زما مرستندوی دی څښتن نه به وېرېږمه زه څه کولای شي انسان ما سره؟', 'نو مونز په داده زره ویلی شو: زما مرستندوی دی چشتن نه به وېرېزمه زه چه کولای شی انسان ما سره؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26427, 'Hebrews 13:7', 'Hebrews', 13, 7, 'خپل مشران چې تاسو ته یې د خدای کلام بیان کړ، په یاد ساتئ. د هغوی د ژوند د لارو او څرنګوالي په هکله فکر وکړئ او د هغوی ایمان د ځان دپاره مثال وګرځوئ.', 'خپل مشران چې تاسو ته یې د خدای کلام بیان کر، په یاد ساتی. د هغوی د ژوند د لارو او چرنګوالی په هکله فکر وکری او د هغوی ایمان د جان دپاره مثال وګرجوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26428, 'Hebrews 13:8', 'Hebrews', 13, 8, 'عیسی مسیح پرون، نن او د تل دپاره یوشان دی.', 'عیسی مسیح پرون، نن او د تل دپاره یوشان دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26429, 'Hebrews 13:9', 'Hebrews', 13, 9, 'د هر ډول عجیبه تعلیمونو له امله مه بې‌لارې کېږئ. دا ښه ده چې زمونږ زړونه د خدای په فضل باندې قوي شي، نه په مذهبي قوانینو پورې تړلي خوړو باندې، ځکه کوم خلک چې دا قانون په مخ وړي هېڅ ګټه ورته نه رسیږي.', 'د هر دول عجیبه تعلیمونو له امله مه بې‌لارې کېزی. دا شه ده چې زمونز زرونه د خدای په فضل باندې قوی شی، نه په مذهبی قوانینو پورې ترلی خورو باندې، جکه کوم خلک چې دا قانون په مخ وری هېچ ګته ورته نه رسیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26430, 'Hebrews 13:10', 'Hebrews', 13, 10, 'مونږ داسې د قربانۍ ځای لرو چې حتی هغه کاهنان چې هلته په سپېڅلې خېمه کې خدمت کوي، د هغې قربانۍ د خوړلو حق نه لري.', 'مونز داسې د قربانی جای لرو چې حتی هغه کاهنان چې هلته په سپېچلې خېمه کې خدمت کوی، د هغې قربانی د خورلو حق نه لری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26431, 'Hebrews 13:11', 'Hebrews', 13, 11, 'ځکه چې لوی کاهن به د حیواناتو وینه د ګناه د قربانۍ په توګه ډېر سپېڅلي ځای ته وړله، خو د هغوی مړي د کمپ نه دباندې سوځول کېدل.', 'جکه چې لوی کاهن به د حیواناتو وینه د ګناه د قربانی په توګه دېر سپېچلی جای ته ورله، خو د هغوی مری د کمپ نه دباندې سوجول کېدل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26432, 'Hebrews 13:12', 'Hebrews', 13, 12, 'نو له دې امله عیسی هم د ښار د دروازې نه دباندې کړاوونه وزغمل او مړ شو، ترڅو د خپلې وینې په وسیله خلک د ګناه څخه پاک کړي.', 'نو له دې امله عیسی هم د شار د دروازې نه دباندې کراوونه وزغمل او مر شو، ترچو د خپلې وینې په وسیله خلک د ګناه چخه پاک کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26433, 'Hebrews 13:13', 'Hebrews', 13, 13, 'نو راځئ چې هغه ته د کمپ نه دباندې ورشو او هغه بې‌عزتي وزغمو چې هغه زغملې وه.', 'نو راجی چې هغه ته د کمپ نه دباندې ورشو او هغه بې‌عزتی وزغمو چې هغه زغملې وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26434, 'Hebrews 13:14', 'Hebrews', 13, 14, 'ځکه چې په دې دنیا کې زمونږ دپاره هېڅ داسې ښار نشته چې د تل دپاره پاتې وي، خو مونږ د هغه ښار په لټه کې یو چې په راتلونکې کې به موجود وي.', 'جکه چې په دې دنیا کې زمونز دپاره هېچ داسې شار نشته چې د تل دپاره پاتې وی، خو مونز د هغه شار په لته کې یو چې په راتلونکې کې به موجود وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26435, 'Hebrews 13:15', 'Hebrews', 13, 15, 'نو راځئ چې د عیسی په وسیله د قربانیو په توګه تل د خدای ثنا او صفت وکړو، یعنې په خپلو خولو د هغه د نوم اقرار وکړو.', 'نو راجی چې د عیسی په وسیله د قربانیو په توګه تل د خدای ثنا او صفت وکرو، یعنې په خپلو خولو د هغه د نوم اقرار وکرو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26436, 'Hebrews 13:16', 'Hebrews', 13, 16, 'نېکي کول او د نورو سره مرسته کول مه هېروئ، ځکه چې خدای په داسې قربانیو خوشحالیږي.', 'نېکی کول او د نورو سره مرسته کول مه هېروی، جکه چې خدای په داسې قربانیو خوشحالیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26437, 'Hebrews 13:17', 'Hebrews', 13, 17, 'د خپلو مشرانو اطاعت کوئ او څه چې درته وایي هماغسې کوئ. هغوی په تاسو باندې پام کوي او خدای ته به حساب ورکوي. نو پرېږدئ چې هغوی دا کار په خوشحالۍ سره وکړي، نه په خفګان. که نه، نو تاسو ته به یې ګټه ونه رسیږي.', 'د خپلو مشرانو اطاعت کوی او چه چې درته وایی هماغسې کوی. هغوی په تاسو باندې پام کوی او خدای ته به حساب ورکوی. نو پرېزدی چې هغوی دا کار په خوشحالی سره وکری، نه په خفګان. که نه، نو تاسو ته به یې ګته ونه رسیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26438, 'Hebrews 13:18', 'Hebrews', 13, 18, 'زمونږ دپاره دعا کوئ. مونږ ډاډمن یو چې زمونږ وجدان پاک دی او غواړو چې په هر لحاظ د عزت ژوند وکړو.', 'زمونز دپاره دعا کوی. مونز دادمن یو چې زمونز وجدان پاک دی او غوارو چې په هر لحاظ د عزت ژوند وکرو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26439, 'Hebrews 13:19', 'Hebrews', 13, 19, 'زه ستاسو نه په کلکه غوښتنه کوم چې دعا وکړئ، ترڅو ډېر زر بېرته تاسو ته راشم. وروستۍ دعاګانې', 'زه ستاسو نه په کلکه غوشتنه کوم چې دعا وکری، ترچو دېر زر بېرته تاسو ته راشم. وروستی دعاګانې', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26440, 'Hebrews 13:20', 'Hebrews', 13, 20, 'اوس دې د سولې او سلامتۍ خدای چې د تلپاتې لوظ د وینې په وسیله یې زمونږ څښتن عیسی چې لوی شپون دی، د مړو نه بېرته راژوندی کړ،', 'اوس دې د سولې او سلامتی خدای چې د تلپاتې لوظ د وینې په وسیله یې زمونز چشتن عیسی چې لوی شپون دی، د مرو نه بېرته راژوندی کر،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26441, 'Hebrews 13:21', 'Hebrews', 13, 21, 'نو هغه دې د خپلې رضا پوره کولو دپاره په خپلو ټولو ښو کارونو کې تیار کړي او د عیسی مسیح په وسیله دې په مونږ کې هغه کارونه وکړي چې هغه پرې خوشحالیږي. د هغه جلال دې تل ترتله وي. امین. وروستني سلامونه', 'نو هغه دې د خپلې رضا پوره کولو دپاره په خپلو تولو شو کارونو کې تیار کری او د عیسی مسیح په وسیله دې په مونز کې هغه کارونه وکری چې هغه پرې خوشحالیزی. د هغه جلال دې تل ترتله وی. امین. وروستنی سلامونه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26442, 'Hebrews 13:22', 'Hebrews', 13, 22, 'ای خویندو او ورونو! ستاسو نه په کلکه غوښتنه کوم چې زما نصیحت په صبر او حوصلې سره واورئ، ځکه چې هغه مې درته په لنډ ډول لیکلی دی.', 'ای خویندو او ورونو! ستاسو نه په کلکه غوشتنه کوم چې زما نصیحت په صبر او حوصلې سره واوری، جکه چې هغه مې درته په لند دول لیکلی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26443, 'Hebrews 13:23', 'Hebrews', 13, 23, 'زه غواړم تاسو خبر شئ چې زمونږ ورور تیموتاوس د زندان نه خلاص شوی دی. که هغه زر دلته راشي، نو هغه به زما سره ستاسو لیدو ته درشي.', 'زه غوارم تاسو خبر شی چې زمونز ورور تیموتاوس د زندان نه خلاص شوی دی. که هغه زر دلته راشی، نو هغه به زما سره ستاسو لیدو ته درشی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26444, 'Hebrews 13:24', 'Hebrews', 13, 24, 'خپلو ټولو مشرانو او ایماندارانو ته زمونږ سلامونه ووایئ. د ایټالیې ایمانداران هم تاسو ته خپل سلامونه وایي.', 'خپلو تولو مشرانو او ایماندارانو ته زمونز سلامونه ووایی. د ایتالیې ایمانداران هم تاسو ته خپل سلامونه وایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26445, 'Hebrews 13:25', 'Hebrews', 13, 25, 'په تاسو ټولو دې د خدای فضل وي.', 'په تاسو تولو دې د خدای فضل وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Hebrews_13_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26446, 'Mark 8:1', 'Mark', 8, 1, 'په هغو ورځو کې یوځل بیا ګڼ شمېر خلک راټول شول او د هغوی سره د خوړلو دپاره هېڅ شی نه ؤ، نو عیسی خپل شاګردان راوغوښتل او ورته ویې ویل:', 'په هغو ورجو کې یوجل بیا ګن شمېر خلک راتول شول او د هغوی سره د خورلو دپاره هېچ شی نه و، نو عیسی خپل شاګردان راوغوشتل او ورته ویې ویل:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26447, 'Mark 8:2', 'Mark', 8, 2, '«په دې خلکو باندې زما زړه سوځي، ځکه چې درې ورځې کیږي هغوی زما سره دي او هېڅ شی ورسره نشته چې ویې خوري.', '«په دې خلکو باندې زما زره سوجی، جکه چې درې ورجې کیزی هغوی زما سره دی او هېچ شی ورسره نشته چې ویې خوری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26448, 'Mark 8:3', 'Mark', 8, 3, 'که چېرې هغوی خپلو کورونو ته وږي رخصت کړم نو په لاره کې به بې‌حاله شي، ځکه چې په هغوی کې ځینې یې د لېرې ځایونو څخه راغلي دي.»', 'که چېرې هغوی خپلو کورونو ته وزی رخصت کرم نو په لاره کې به بې‌حاله شی، جکه چې په هغوی کې جینې یې د لېرې جایونو چخه راغلی دی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26449, 'Mark 8:4', 'Mark', 8, 4, 'شاګردانو یې ځواب ورکړ: «په دې دښته کې څوک دومره خلکو ته ډوډۍ ورکولای شي؟»', 'شاګردانو یې جواب ورکر: «په دې دشته کې چوک دومره خلکو ته دودی ورکولای شی؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26450, 'Mark 8:5', 'Mark', 8, 5, 'عیسی پوښتنه وکړه: «تاسو سره څو ډوډۍ دي؟» هغوی ځواب ورکړ: «اووه ډوډۍ.»', 'عیسی پوشتنه وکره: «تاسو سره چو دودی دی؟» هغوی جواب ورکر: «اووه دودی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26451, 'Mark 8:6', 'Mark', 8, 6, 'نو عیسی خلکو ته وویل چې په ځمکه کښېني. بیا یې هغه اووه ډوډۍ راواخیستلې، د خدای شکر یې وویست، ډوډۍ یې ماتې کړې او شاګردانو ته یې ورکړلې چې په خلکو باندې یې ووېشي او شاګردانو همداسې وکړل.', 'نو عیسی خلکو ته وویل چې په جمکه کشېنی. بیا یې هغه اووه دودی راواخیستلې، د خدای شکر یې وویست، دودی یې ماتې کرې او شاګردانو ته یې ورکرلې چې په خلکو باندې یې ووېشی او شاګردانو همداسې وکرل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26452, 'Mark 8:7', 'Mark', 8, 7, 'د هغوی سره یو څو واړه ماهیان هم وو. عیسی په هغو هم شکر وویست او شاګردانو ته یې وویل چې هغه هم ووېشي.', 'د هغوی سره یو چو واره ماهیان هم وو. عیسی په هغو هم شکر وویست او شاګردانو ته یې وویل چې هغه هم ووېشی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26453, 'Mark 8:8', 'Mark', 8, 8, 'خلکو هغه وخوړل او ټول ورباندې ماړه شول او د ډوډۍ د پاتې شویو ټوټو نه اووه ټوکرۍ ډکې شوې.', 'خلکو هغه وخورل او تول ورباندې ماره شول او د دودی د پاتې شویو توتو نه اووه توکری دکې شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26454, 'Mark 8:9', 'Mark', 8, 9, 'په هغه ځای کې نژدې څلور زره کسان وو. عیسی هغوی رخصت کړل،', 'په هغه جای کې نژدې چلور زره کسان وو. عیسی هغوی رخصت کرل،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26455, 'Mark 8:10', 'Mark', 8, 10, 'او سمدلاسه د خپلو شاګردانو سره په کشتۍ کې سپور شو او د دلمانوته سیمې ته لاړ. د فریسیانو له خوا د معجزې غوښتنه (متي ۱۶‏:‌۱‌‏-‌۴)', 'او سمدلاسه د خپلو شاګردانو سره په کشتی کې سپور شو او د دلمانوته سیمې ته لار. د فریسیانو له خوا د معجزې غوشتنه (متی ۱۶‏:‌۱‌‏-‌۴)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26456, 'Mark 8:11', 'Mark', 8, 11, 'فریسیان راغلل او د عیسی سره یې بحث پیل کړ او د دې دپاره چې هغه وازمایي، نو د هغه څخه یې وغوښتل چې دوی ته یوه اسماني معجزه وښایي.', 'فریسیان راغلل او د عیسی سره یې بحث پیل کر او د دې دپاره چې هغه وازمایی، نو د هغه چخه یې وغوشتل چې دوی ته یوه اسمانی معجزه وشایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26457, 'Mark 8:12', 'Mark', 8, 12, 'هغه یو سوړ اوسېلی وویست او ویې ویل: «د دې زمانې خلک ولې معجزه غواړي؟ په یقین سره زه تاسو ته دا وایم چې دې خلکو ته به هېڅ یوه معجزه ونه ښودل شي.»', 'هغه یو سور اوسېلی وویست او ویې ویل: «د دې زمانې خلک ولې معجزه غواری؟ په یقین سره زه تاسو ته دا وایم چې دې خلکو ته به هېچ یوه معجزه ونه شودل شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26458, 'Mark 8:13', 'Mark', 8, 13, 'بیا عیسی هغوی پرېښودل او بېرته په کشتۍ کې کښېناست او د بحیرې بلې غاړې ته لاړ. د فریسیانو او هیرودیس د تعلیم څخه لېرې اوسئ (متي ۱۶‏:‌۵‌‏-‌۱۲)', 'بیا عیسی هغوی پرېشودل او بېرته په کشتی کې کشېناست او د بحیرې بلې غارې ته لار. د فریسیانو او هیرودیس د تعلیم چخه لېرې اوسی (متی ۱۶‏:‌۵‌‏-‌۱۲)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26459, 'Mark 8:14', 'Mark', 8, 14, 'شاګردانو دا هېر کړي وو چې د ځان سره ډوډۍ یوسي او په کشتۍ کې د هغوی سره یوازې یوه ډوډۍ وه.', 'شاګردانو دا هېر کری وو چې د جان سره دودی یوسی او په کشتی کې د هغوی سره یوازې یوه دودی وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26460, 'Mark 8:15', 'Mark', 8, 15, 'عیسی هغوی ته امر وکړ او ویې ویل: «پام کوئ، د فریسیانو او هیرودیس د خمیرې نه به ځانونه ساتئ.»', 'عیسی هغوی ته امر وکر او ویې ویل: «پام کوی، د فریسیانو او هیرودیس د خمیرې نه به جانونه ساتی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Mark_8_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833);